-- Authorized original data-structure single-choice import based on:
-- /Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf
-- Chapter 5: 5.3.3/5.3.4 and 5.4.4/5.4.5 本节试题精选 / 答案与解析
-- Batch: DS-2027-ORIGINAL-CH5-G

CREATE TABLE ds_2027_original_ch5_g_import (
    num INTEGER PRIMARY KEY,
    id VARCHAR(36) NOT NULL,
    difficulty VARCHAR(16) NOT NULL,
    source_type VARCHAR(32) NOT NULL,
    source_year INTEGER,
    section_tag VARCHAR(64) NOT NULL,
    source_pages VARCHAR(64) NOT NULL,
    stem TEXT NOT NULL,
    answer TEXT NOT NULL,
    explanation TEXT NOT NULL,
    stem_format VARCHAR(32) NOT NULL DEFAULT 'PLAIN_TEXT',
    stem_image_url VARCHAR(512),
    option_a TEXT NOT NULL,
    option_b TEXT NOT NULL,
    option_c TEXT NOT NULL,
    option_d TEXT NOT NULL
);

INSERT INTO ds_2027_original_ch5_g_import (
    num, id, difficulty, source_type, source_year, section_tag, source_pages,
    stem, answer, explanation, stem_format, stem_image_url,
    option_a, option_b, option_c, option_d
) VALUES
(25, '00000000-0000-0000-0000-000000059025', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,155', '一棵左子树为空的二叉树在先序线索化后，其中空的链域的个数是（ ）。', 'D', '对左子树为空的二叉树进行先序线索化，根结点的左子树为空且没有前驱，先序遍历的最后一个元素为叶结点，左右子树均为空且有前驱无后继结点，所以线索化后树中空链域有 2 个。', 'PLAIN_TEXT', NULL, '不确定', '0 个', '1 个', '2 个'),
(26, '00000000-0000-0000-0000-000000059026', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,155', '在线索二叉树中，下列说法不正确的是（ ）。', 'D', '不是每个结点都能通过线索查到前驱和后继。先序线索树查找先序后继较简单，但查找先序前驱必须知道该结点的双亲；后序线索树查找后序前驱较简单，查找后序后继也必须知道双亲。二叉链表中没有存放双亲的指针。', 'PLAIN_TEXT', NULL, '在中序线索树中，若某结点有右孩子，则其后继结点是它的右子树的最左下结点', '在中序线索树中，若某结点有左孩子，则其前驱结点是它的左子树的最右下结点', '线索二叉树是利用二叉树的 n+1 个空指针来存放结点的前驱和后继信息的', '每个结点通过线索都可以直接找到它的前驱和后继'),
(27, '00000000-0000-0000-0000-000000059027', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,155-156', '二叉树在线索化后，仍不能有效求解的问题是（ ）。', 'D', '后序线索二叉树不能有效解决求后序后继的问题。例如某结点的右指针指向右孩子，而在后序序列中它的后继结点可能是其双亲；查找后序后继仍需知道双亲信息。', 'PLAIN_TEXT', NULL, '先序线索二叉树中求先序后继', '中序线索二叉树中求中序后继', '中序线索二叉树中求中序前驱', '后序线索二叉树中求后序后继'),
(28, '00000000-0000-0000-0000-000000059028', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '若 X 是二叉中序线索树中一个有左孩子的结点，且 X 不为根，则 X 的前驱为（ ）。', 'C', '在二叉中序线索树中，若某结点有左孩子，则按照中序“左根右”的顺序，该结点的前驱结点为其左子树中最右的一个结点。', 'PLAIN_TEXT', NULL, 'X 的双亲', 'X 的右子树中最左的结点', 'X 的左子树中最右的结点', 'X 的左子树中最右的叶结点'),
(29, '00000000-0000-0000-0000-000000059029', 'BASIC', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '若 X 是后序线索二叉树中的叶结点，且 X 存在左兄弟 Y，则 X 的右线索指向的是（ ）。', 'A', '在二叉树的后序遍历中，叶结点 X 的后继是其双亲，因此 X 的右线索应指向该结点。', 'PLAIN_TEXT', NULL, 'X 的双亲', '以 Y 为根的子树的最左下结点', 'X 的左兄弟 Y', '以 Y 为根的子树的最右下结点'),
(30, '00000000-0000-0000-0000-000000059030', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '某二叉树的先序序列和后序序列正好相反，则该二叉树一定是（ ）。', 'B', '非空二叉树的先序序列和后序序列相反，即“根左右”与“左右根”顺序相反。只有任意结点至多只有一个孩子时才满足该性质，此时树形为一条长链，树中只有一个叶结点。', 'PLAIN_TEXT', NULL, '空或只有一个结点', '高度等于其结点数', '任意一个结点无左孩子', '任意一个结点无右孩子'),
(31, '00000000-0000-0000-0000-000000059031', 'MEDIUM', 'MOCK', 2027, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '某非空二叉树的先序序列和中序序列正好相反，则下列叙述中正确的是（ ）。', 'D', '非空二叉树的先序序列和中序序列相反，即“根左右”与“左根右”顺序相反，因此树只含根结点，或任意结点只有左孩子，树形是一棵向左倾斜的单支树。但只有一个叶结点不能保证任意结点无右孩子。', 'PLAIN_TEXT', NULL, '该二叉树一定只有一个结点', '只有一个叶结点的二叉树一定满足条件', '任意一个结点无左孩子的二叉树一定满足条件', '任意一个结点无右孩子的二叉树一定满足条件'),
(32, '00000000-0000-0000-0000-000000059032', 'MEDIUM', 'PAST_EXAM', 2009, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '【2009 统考真题】给定二叉树如题图所示。设 N 代表二叉树的根，L 代表根结点的左子树，R 代表根结点的右子树。若遍历后的结点序列是 3175624，则其遍历方式是（ ）。', 'D', '分析遍历后的结点序列，可看出根结点是在中间被访问的，而且右子树结点在左子树之前，则遍历方法是 RNL。本题考查的并不是二叉树遍历的 3 种基本遍历方法，而是遍历思想。', 'DIAGRAM', '/question-assets/ds-2027/ch5/q32-traversal-tree.png', 'LRN', 'NRL', 'RLN', 'RNL'),
(33, '00000000-0000-0000-0000-000000059033', 'HARD', 'PAST_EXAM', 2010, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '【2010 统考真题】下列线索二叉树中（用虚线表示线索），符合后序线索树定义的是（ ）。', 'D', '题中所给二叉树的后序序列为 dbca。结点 d 无前驱和左子树，左链域空；无右子树，右链域指向其后继结点 b。结点 b 无左子树，左链域指向其前驱结点 d。结点 c 无左子树，左链域指向其前驱结点 b；无右子树，右链域指向其后继结点 a。与选项 D 相符。', 'DIAGRAM', '/question-assets/ds-2027/ch5/q33-thread-options.png', '见题图 A', '见题图 B', '见题图 C', '见题图 D'),
(34, '00000000-0000-0000-0000-000000059034', 'HARD', 'PAST_EXAM', 2011, '5.3二叉树的遍历和线索二叉树', 'pp.149,156', '【2011 统考真题】一棵二叉树的先序遍历序列和后序遍历序列分别为 1,2,3,4 和 4,3,2,1，该二叉树的中序遍历序列不会是（ ）。', 'C', '先序序列为 NLR，后序序列为 LRN，二者正好相反，说明不可能有结点同时有左右孩子。逐项分析可得 A、B、D 均可构造对应二叉树，选项 C 不可能。', 'PLAIN_TEXT', NULL, '1,2,3,4', '2,3,4,1', '3,2,4,1', '4,3,2,1'),
(35, '00000000-0000-0000-0000-000000059035', 'HARD', 'PAST_EXAM', 2012, '5.3二叉树的遍历和线索二叉树', 'pp.150,156-157', '【2012 统考真题】若一棵二叉树的先序遍历序列为 a,e,b,d,c，后序遍历序列为 b,c,d,e,a，则根结点的孩子结点（ ）。', 'A', '先序和后序遍历不能唯一确定一棵二叉树，但可以确定结点间的祖先关系。由先序 a,e,b,d,c 和后序 b,c,d,e,a 可知 a 为根结点，e 为 a 的孩子结点；再结合 e 的子树遍历关系可排除其他选项。', 'PLAIN_TEXT', NULL, '只有 e', '有 e、b', '有 e、c', '无法确定'),
(36, '00000000-0000-0000-0000-000000059036', 'MEDIUM', 'PAST_EXAM', 2013, '5.3二叉树的遍历和线索二叉树', 'pp.150,157', '【2013 统考真题】若 X 是后序线索二叉树中的叶结点，且 X 存在左兄弟结点 Y，则 X 的右线索指向的是（ ）。', 'A', '根据后序线索二叉树的定义，X 结点为叶结点且有左兄弟，则 X 为右孩子结点。利用后序遍历可知 X 结点的后序后继是其父结点，即右线索指向的是父结点。', 'PLAIN_TEXT', NULL, 'X 的父结点', '以 Y 为根的子树的最左下结点', 'X 的左兄弟结点 Y', '以 Y 为根的子树的最右下结点'),
(37, '00000000-0000-0000-0000-000000059037', 'MEDIUM', 'PAST_EXAM', 2014, '5.3二叉树的遍历和线索二叉树', 'pp.150,157', '【2014 统考真题】若对右图所示的二叉树进行中序线索化，则结点 X 的左右线索指向的结点分别是（ ）。', 'D', '线索二叉树中的线索指向相应遍历序列中某结点的前驱和后继。写出二叉树的中序遍历序列为 debxac，中序遍历中在 X 左边和右边的字符，就是它在中序线索化时的左、右线索，即 b、a。', 'DIAGRAM', '/question-assets/ds-2027/ch5/q37-thread-tree.png', 'e, c', 'e, a', 'd, c', 'b, a'),
(38, '00000000-0000-0000-0000-000000059038', 'HARD', 'PAST_EXAM', 2015, '5.3二叉树的遍历和线索二叉树', 'pp.150,157', '【2015 统考真题】先序序列为 a,b,c,d 的不同二叉树的个数是（ ）。', 'B', '二叉树先序遍历和中序遍历的递归算法中，若以先序序列为入栈次序、中序序列为出栈次序，则对 n 个不同元素，出栈序列的个数为 Catalan 数 C(2n,n)/(n+1)。当 n=4 时为 14。', 'PLAIN_TEXT', NULL, '13', '14', '15', '16'),
(39, '00000000-0000-0000-0000-000000059039', 'MEDIUM', 'PAST_EXAM', 2017, '5.3二叉树的遍历和线索二叉树', 'pp.150,157', '【2017 统考真题】某二叉树的树形如右图所示，其后序序列为 e,a,c,b,d,g,f，树中与结点 a 同层的结点是（ ）。', 'B', '后序序列先访问左子树、接着访问右子树、最后访问父结点。由后序序列可确定题图中结点关系：e 为 a 的左孩子，a 的父结点为 c；b 的父结点为 d，d 的父结点为 g，最后为根结点 f，因此 d 与 a 同层。', 'DIAGRAM', '/question-assets/ds-2027/ch5/q39-tree-shape.png', 'c', 'd', 'f', 'g'),
(40, '00000000-0000-0000-0000-000000059040', 'MEDIUM', 'PAST_EXAM', 2017, '5.3二叉树的遍历和线索二叉树', 'pp.150,157', '【2017 统考真题】要使一棵非空二叉树的先序序列与中序序列相同，其所有非叶结点须满足的条件是（ ）。', 'B', '先序序列先访问父结点，再访问左右子树；中序序列先访问左子树，再访问父结点，然后访问右子树。若所有非叶结点只有右子树，则先序序列和中序序列都会先访问父结点，后访问右子树。', 'PLAIN_TEXT', NULL, '只有左子树', '只有右子树', '结点的度均为 1', '结点的度均为 2'),
(41, '00000000-0000-0000-0000-000000059041', 'HARD', 'PAST_EXAM', 2022, '5.3二叉树的遍历和线索二叉树', 'pp.150,157-158', '【2022 统考真题】若结点 p 与 q 在二叉树 T 的中序遍历序列中相邻，且 p 在 q 之前，则下列 p 与 q 的关系中，不可能的是（ ）。\nI. q 是 p 的双亲\nII. q 是 p 的右孩子\nIII. q 是 p 的右兄弟\nIV. q 是 p 的双亲的双亲', 'B', '此类题每种情况只需举出反例。q 是 p 的双亲、q 是 p 的右孩子、q 是 p 的双亲的双亲都可能出现在相邻中序序列中；若 q 是 p 的右兄弟，则 p 和 q 中间一定先访问其父结点，因此不可能相邻出现。', 'PLAIN_TEXT', NULL, '仅 I', '仅 III', '仅 II、III', '仅 II、IV'),
(42, '00000000-0000-0000-0000-000000059042', 'MEDIUM', 'PAST_EXAM', 2023, '5.3二叉树的遍历和线索二叉树', 'pp.150,158', '【2023 统考真题】已知一棵二叉树的树形如右图所示，若其后序遍历序列为 fdbeca，则其先（前）序遍历序列是（ ）。', 'A', '根据二叉树的树形和后序遍历序列，可依次把字母填入结点中。再对该二叉树进行先序遍历，得到序列 aedfbc。', 'DIAGRAM', '/question-assets/ds-2027/ch5/q42-tree-shape.png', 'aedfbc', 'acebdf', 'cabefd', 'dfebac'),
(43, '00000000-0000-0000-0000-000000059043', 'HARD', 'PAST_EXAM', 2024, '5.3二叉树的遍历和线索二叉树', 'pp.150,158', '【2024 统考真题】若 p、q 和 v 均为二叉树 T 中的结点，v 有两个孩子结点，T 的中序遍历序列形如“..., p, v, q, ...”，则在下列叙述中，正确的是（ ）。', 'A', '中序遍历中，v 的左子树在 v 前，右子树在 v 后。若 p 有右孩子，则 p 的右孩子会在中序序列中位于 p 之后，与 p 是最后一个遍历结点矛盾，因此 p 没有右孩子；同理，q 若有左孩子，则其左孩子应在 q 之前，与 q 是第一个遍历结点矛盾，因此 q 没有左孩子。', 'PLAIN_TEXT', NULL, 'p 没有右孩子，q 没有左孩子', 'p 没有右孩子，q 有左孩子', 'p 有右孩子，q 没有左孩子', 'p 有右孩子，q 有左孩子'),
(101, '00000000-0000-0000-0000-000000059101', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.172,175', '下列关于树的说法中，正确的是（ ）。\nI. 对于有 n 个结点的二叉树，其高度为 log2n\nII. 完全二叉树中，若一个结点没有左孩子，则它必是叶结点\nIII. 高度为 h（h>0）的完全二叉树对应的森林所含的树的个数一定是 h\nIV. 一棵树中的叶子数一定等于与其对应的二叉树的叶子数', 'D', '若 n 个结点的二叉树是一棵单支树，则其高度为 n，故 I 错。完全二叉树中若不存在左孩子，则一定不存在右孩子，因此必是叶结点，II 正确。只有满二叉树才具有 III 的性质。树转换为二叉树后，若多个叶结点具有共同双亲，则转换后的二叉树只有最右边的叶结点仍为叶结点，IV 错。', 'PLAIN_TEXT', NULL, 'I 和 III', 'IV', 'I 和 II', 'II'),
(102, '00000000-0000-0000-0000-000000059102', 'BASIC', 'MOCK', 2027, '5.4树、森林', 'pp.172,175', '利用二叉链表存储森林时，根结点的右指针是（ ）。', 'D', '森林与二叉树具有对应关系，存储森林时应先将森林转换为二叉树。若存在第二棵树，则二叉链表根结点的右指针指向森林中第二棵树的根结点；若森林只有一棵树，则根结点的右指针为空。因此右指针可能为空也可能不为空。', 'PLAIN_TEXT', NULL, '指向最左兄弟', '指向最右兄弟', '一定为空', '不一定为空'),
(103, '00000000-0000-0000-0000-000000059103', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.172,175', '设森林 F 中有 3 棵树，第 1、2、3 棵树的结点数分别为 M1、M2 和 M3，与森林 F 对应的二叉树根结点的右子树上的结点数是（ ）。', 'D', '与树转换为二叉树不同，森林中的每棵树都是独立的，需先将每棵树的根结点都视为兄弟结点。森林转换为二叉树后，树 2 作为树 1 根结点的右子树，树 3 作为树 2 根结点的右子树，所以根结点右子树上的结点数为 M2+M3。', 'PLAIN_TEXT', NULL, 'M1', 'M1+M2', 'M3', 'M2+M3'),
(104, '00000000-0000-0000-0000-000000059104', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.172,175', '设森林 F 中有 4 棵树，第 1、2、3、4 棵树的结点数分别为 a、b、c 和 d，与森林 F 对应的二叉树的根结点的左子树上的结点数是（ ）。', 'C', '森林转换为二叉树后，二叉树的根结点为第 1 棵树的根结点，二叉树根结点的左子树包含第 1 棵树的所有孩子，因此森林 F 对应的二叉树根结点的左子树上的结点数是 a-1。', 'PLAIN_TEXT', NULL, 'a', 'b+c+d', 'a-1', 'a+b+c'),
(105, '00000000-0000-0000-0000-000000059105', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.172-173,175', '设森林 F 对应的二叉树为 B，它有 m 个结点，B 的根为 p，p 的右子树结点数为 n，森林 F 中第一棵树的结点数是（ ）。', 'A', '森林转换成二叉树时采用孩子兄弟表示法，根结点及其左子树为森林中的第一棵树，右子树为其他剩余的树。所以，第一棵树的结点数为 m-n。', 'PLAIN_TEXT', NULL, 'm-n', 'm-n-1', 'n+1', '条件不足，无法确定'),
(106, '00000000-0000-0000-0000-000000059106', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.173,175', '设森林 F 对应的二叉树是一棵具有 16 个结点的完全二叉树，则森林 F 中树的数目和结点最多的树的结点数分别是（ ）。', 'D', '森林转换为二叉树后，二叉树的根结点及其左子树由第 1 棵树转换得到，二叉树根结点的右子树由剩余森林转换得到。由具有 16 个结点的完全二叉树可划分出第 2、3、4 棵树的结点，故森林中有 4 棵树，其中第 1 棵树的结点数最多，有 9 个。', 'PLAIN_TEXT', NULL, '2 和 8', '2 和 9', '4 和 8', '4 和 9'),
(107, '00000000-0000-0000-0000-000000059107', 'HARD', 'MOCK', 2027, '5.4树、森林', 'pp.173,176', '森林 T=(T1,T2,...,Tm) 转化为二叉树 BT 的过程为：若 m=0，则 BT 为空，若 m≠0，则（ ）。', 'B', '将森林中每棵树的根结点视为兄弟结点的关系，再按照“左孩子右兄弟”的规则进行转化。T1 的根作为 BT 的根；T1 的子树森林转换成 BT 的左子树；T2 到 Tm 转换成 BT 的右子树。', 'PLAIN_TEXT', NULL, '将中间子树 Tmid 的根作为 BT 的根；将前半部分转换为左子树，将后半部分转换为右子树', '将子树 T1 的根作为 BT 的根；将 T1 的子树森林转换成 BT 的左子树；将 (T2,T3,...,Tm) 转换成 BT 的右子树', '将子树 T1 的根作为 BT 的根；将 T1 的左子树森林转换成 BT 的左子树；将 T1 的右子树森林转换成 BT 的右子树；其他以此类推', '将森林 T 的根作为 BT 的根；将 (T1,T2,...,Tm) 转化为该根下的结点，得到一棵树，然后将这棵树再转化为二叉树 BT'),
(108, '00000000-0000-0000-0000-000000059108', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.173,176', '设 F 是一个森林，B 是由 F 变换来的二叉树。若 F 中有 n 个非终端结点，则 B 中右指针域为空的结点有（ ）个。', 'C', '根据森林与二叉树转换规则“左孩子右兄弟”，二叉树 B 中右指针域为空代表该结点没有兄弟结点。森林中每棵树的根结点从第二个开始依次连接到前一棵树根的右孩子，最后一棵树根结点的右指针为空；每个非终端结点的所有孩子结点转换后，最后一个孩子的右指针也为空，所以右指针域为空的结点有 n+1 个。', 'PLAIN_TEXT', NULL, 'n-1', 'n', 'n+1', 'n+2'),
(109, '00000000-0000-0000-0000-000000059109', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.173,176', '设某树的孩子兄弟链表表示中共有 6 个空的左指针域，7 个空的右指针域，包括 5 个结点的左右指针域均为空，则该树中叶结点的个数是（ ）。', 'B', '在树的孩子兄弟表示法中，若一个结点没有孩子（叶结点），则表现为该结点的左指针域为空。本题给出 6 个空的左指针域，所以叶结点个数为 6。题中“5 个结点的左右指针域均为空”是更严格的附加条件，但求叶结点个数仍由空左指针域确定。', 'PLAIN_TEXT', NULL, '7', '6', '5', '不能确定'),
(110, '00000000-0000-0000-0000-000000059110', 'MEDIUM', 'MOCK', 2027, '5.4树、森林', 'pp.173,176', '若 T1 是由有序树 T 转换而来的二叉树，则 T 中结点的后根序列就是 T1 中结点的（ ）序列。', 'B', '有序树 T 转换成二叉树 T1 时，T 的后根序列对应 T1 的中序序列，而不可能对应 T1 的先序序列或层序序列。可用简单树转换为二叉树后验证：树中叶结点应先访问，而二叉树中对应结点在中序序列中先出现。', 'PLAIN_TEXT', NULL, '先序', '中序', '后序', '层序'),
(111, '00000000-0000-0000-0000-000000059111', 'HARD', 'MOCK', 2027, '5.4树、森林', 'pp.173,176', '某二叉树结点的中序序列为 BDAECF，后序序列为 DBEFCA，则该二叉树对应的森林包括（ ）棵树。', 'C', '根据二叉树的后序序列和中序序列可确定该二叉树。后序序列最后一个结点 A 为根；由中序序列可确定其左右子树结构，再根据二叉树与森林的对应关系，森林中树的棵数即对应二叉树向右上旋转后根结点 A 及其右兄弟数，可知森林中有 3 棵树，根结点分别为 A、C 和 F。', 'PLAIN_TEXT', NULL, '1', '2', '3', '4');

INSERT INTO questions (
    id, subject_id, chapter_id, type, difficulty, stem, answer, explanation,
    source, source_year, score, status, review_status, review_note,
    stem_format, stem_image_url, reviewed_at, created_at, updated_at
)
SELECT
    CAST(q.id AS UUID),
    s.id,
    c.id,
    'SINGLE_CHOICE',
    q.difficulty,
    q.stem,
    q.answer,
    q.explanation,
    q.source_type,
    q.source_year,
    2.00,
    'PUBLISHED',
    'APPROVED',
    '授权原题导入：/Users/permer/Documents/408资料/2027数据结构_高清带书签版.pdf，第 5 章 5.3.3/5.3.4 与 5.4.4/5.4.5 本节试题精选及答案解析，参考页：' || q.source_pages || '。',
    q.stem_format,
    q.stem_image_url,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM ds_2027_original_ch5_g_import q
JOIN subjects s ON s.code = 'DATA_STRUCTURE'
JOIN chapters c ON c.code = 'DS_TREE';

INSERT INTO question_options (id, question_id, label, content, sort_order)
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000159', LPAD(CAST((num * 4 - 3) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'A', option_a, 1
FROM ds_2027_original_ch5_g_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000159', LPAD(CAST((num * 4 - 2) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'B', option_b, 2
FROM ds_2027_original_ch5_g_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000159', LPAD(CAST((num * 4 - 1) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'C', option_c, 3
FROM ds_2027_original_ch5_g_import
UNION ALL
SELECT CAST(CONCAT('00000000-0000-0000-0000-000000159', LPAD(CAST((num * 4) AS VARCHAR), 3, '0')) AS UUID), CAST(id AS UUID), 'D', option_d, 4
FROM ds_2027_original_ch5_g_import;

INSERT INTO question_knowledge_points (question_id, knowledge_point_id)
SELECT CAST(q.id AS UUID), kp.id
FROM ds_2027_original_ch5_g_import q
JOIN knowledge_points kp ON kp.code = 'DS_TREE_TRAVERSAL';

INSERT INTO question_tags (id, name, created_at)
SELECT CAST(tag.id AS UUID), tag.name, CURRENT_TIMESTAMP
FROM (
    VALUES
    ('00000000-0000-0000-0000-000000059701', 'DS-2027-ORIGINAL-CH5-G'),
    ('00000000-0000-0000-0000-000000059702', '5.4树、森林')
) AS tag(id, name)
WHERE NOT EXISTS (SELECT 1 FROM question_tags existing WHERE existing.name = tag.name);

INSERT INTO question_tag_relations (question_id, tag_id)
SELECT CAST(q.id AS UUID), tag.id
FROM ds_2027_original_ch5_g_import q
JOIN question_tags tag ON tag.name IN (
    '2027数据结构',
    'DS-2027-ORIGINAL-CH5-G',
    '第5章树与二叉树',
    q.section_tag,
    '授权原题',
    '本节试题精选',
    '原答案解析',
    '选择题扩容'
) OR (q.source_type = 'PAST_EXAM' AND tag.name = '真题')
WHERE NOT EXISTS (
    SELECT 1 FROM question_tag_relations existing
    WHERE existing.question_id = CAST(q.id AS UUID)
      AND existing.tag_id = tag.id
);

DROP TABLE ds_2027_original_ch5_g_import;
